"""``catalog.txt``: what the shop sells."""

import re
from dataclasses import dataclass
from decimal import Decimal

from ._text import BLANK, SKU_RE, content_lines, parse_uint
from .errors import ParseError

TAX_RATES = {"standard": 20, "reduced": 5, "zero": 0}
_PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
_MIN_PRICE = Decimal("0.01")


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


def parse_catalog(text):
    """Parse ``catalog.txt`` text into a ``dict`` of SKU to :class:`Product`."""
    catalog = {}
    for number, line in content_lines(text):
        fields = [field.strip(BLANK) for field in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                number,
                "expected 4 or 5 fields separated by '|', found %d" % len(fields),
            )
        sku_text, name, price_text, reorder_text = fields[:4]
        if not SKU_RE.fullmatch(sku_text):
            raise ParseError(number, "bad SKU %r (expected like AB-100)" % sku_text)
        sku = sku_text.upper()
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "product name is empty")
        if not _PRICE_RE.fullmatch(price_text) or Decimal(price_text) < _MIN_PRICE:
            raise ParseError(
                number,
                "bad price %r (pounds, at least 0.01, at most two decimals)"
                % price_text,
            )
        reorder = parse_uint(reorder_text)
        if reorder is None:
            raise ParseError(
                number, "bad reorder level %r (whole number, 0 or more)" % reorder_text
            )
        tax = fields[4].lower() if len(fields) == 5 else "standard"
        if tax not in TAX_RATES:
            raise ParseError(
                number, "bad tax %r (standard, reduced or zero)" % fields[4]
            )
        catalog[sku] = Product(sku, name, Decimal(price_text), reorder, tax)
    return catalog

