    # The brief: tax is "standard when the field is left out"; a trailing
    # '|' (or only whitespace after it) leaves the field out.
    for line in ["AB-100|n|1|0|", "AB-100|n|1|0|   ", "AB-100|n|1|0|\t"]:
        self.assertEqual(parse_catalog(line + "\n")["AB-100"].tax, "standard")

